-- Audit Trigger for INSERT on encounters
CREATE TRIGGER IF NOT EXISTS trg_audit_insert_encounters
AFTER INSERT ON encounters
FOR EACH ROW
BEGIN
  SELECT RAISE(ABORT, 'Direct mutation prohibited without active _request_ctx')
  WHERE (SELECT COUNT(*) FROM _request_ctx WHERE id = 1) = 0;

  INSERT INTO audit_log (
    at, actor_id, action, table_name, record_id, patient_id, old_row, new_row
  )
  VALUES (
    datetime('now'),
    (SELECT actor_id FROM _request_ctx WHERE id = 1),
    'INSERT',
    'encounters',
    NEW.id,
    NEW.patient_id,
    NULL,
    json_object('id', NEW.id, 'patient_id', NEW.patient_id, 'doctor_id', NEW.doctor_id, 'department_id', NEW.department_id, 'status', NEW.status, 'sensitivity', NEW.sensitivity, 'chief_complaint', NEW.chief_complaint, 'clinical_notes', NEW.clinical_notes, 'examination', NEW.examination, 'diagnosis', NEW.diagnosis, 'signed_at', NEW.signed_at, 'created_at', NEW.created_at, 'updated_at', NEW.updated_at)
  );
END;

